<?php

namespace Tests\Feature;

use App\Models\Site;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Blade;
use Illuminate\Support\Facades\Process;
use Tests\TestCase;

/** The install snippets the dashboard offers per framework. They are generated by public/assets/js/snippets.js, which runs here under Node. */
class FrameworkSnippetsTest extends TestCase
{
    use RefreshDatabase;

    private const ORIGIN = 'https://stats.example.com';

    /** @var string[] */
    private array $temporaryFiles = [];

    protected function tearDown(): void
    {
        array_map('unlink', $this->temporaryFiles);

        parent::tearDown();
    }

    public function test_every_framework_snippet_loads_the_sites_own_script_file(): void
    {
        $site = Site::create(['domain' => 'example.com', 'track_outbound' => true]);

        foreach ($this->snippets($site) as $framework => $snippet) {
            $this->assertNotSame('', $snippet['where'], $framework);
            if ($framework === 'wordpress') {
                continue;
            }
            $this->assertStringContainsString('example.com', $snippet['text'], $framework);
            $this->assertStringContainsString(self::ORIGIN.'/js/'.$site->scriptName(), $snippet['text'], $framework);
        }

        $this->get('/js/'.$site->scriptName())->assertOk();
    }

    public function test_the_picker_lists_each_framework_once_and_an_unknown_one_falls_back_to_plain_html(): void
    {
        $site = Site::create(['domain' => 'example.com']);
        $snippets = $this->snippets($site, ['unknown']);

        $keys = array_keys($this->snippets($site));
        $this->assertSame($keys, array_unique($keys));
        $this->assertEqualsCanonicalizing(['html', 'wordpress', 'shopify', 'next', 'nuxt', 'astro', 'sveltekit', 'laravel'], $keys);
        $this->assertSame($this->snippets($site)['html'], $snippets['unknown']);
    }

    public function test_the_plain_tag_is_used_unchanged_where_the_framework_takes_html(): void
    {
        $site = Site::create(['domain' => 'example.com']);
        $tag = '<script defer data-domain="example.com" src="'.self::ORIGIN.'/js/'.$site->scriptName().'"></script>';

        foreach (['html', 'sveltekit', 'shopify'] as $framework) {
            $this->assertSame($tag, $this->snippets($site)[$framework]['text'], $framework);
        }
        $this->assertSame(str_replace('<script', '<script is:inline', $tag), $this->snippets($site)['astro']['text']);
    }

    public function test_the_wordpress_entry_gives_the_address_for_the_plugin_and_links_to_it(): void
    {
        $site = Site::create(['domain' => 'example.com']);
        $wordpress = $this->snippets($site)['wordpress'];

        $this->assertSame(self::ORIGIN, $wordpress['text']);
        $this->assertSame('https://wordpress.org/plugins/tidemark-analytics/', $wordpress['link']['href']);
        $this->assertStringContainsString('example.com', $wordpress['where']);
    }

    public function test_the_groups_hold_every_framework_exactly_once(): void
    {
        $site = Site::create(['domain' => 'example.com']);
        $module = $this->temporaryFile('mjs', file_get_contents(public_path('assets/js/snippets.js')));

        $grouped = json_decode($this->runNode(
            "import { FRAMEWORK_GROUPS } from 'file://{$module}'; console.log(JSON.stringify(FRAMEWORK_GROUPS.flatMap(([, items]) => items.map(([key]) => key))));",
            module: true,
        ), true);

        $this->assertSame($grouped, array_keys($this->snippets($site)));
    }

    public function test_the_nuxt_snippet_is_a_valid_config_that_declares_the_script(): void
    {
        $site = Site::create(['domain' => 'example.com']);
        $source = 'const defineNuxtConfig = (config) => config; const config = '.substr($this->snippets($site)['nuxt']['text'], strlen('export default '));

        $result = $this->runNode($source.' console.log(JSON.stringify(config.app.head.script));');

        $this->assertSame(
            [['src' => self::ORIGIN.'/js/'.$site->scriptName(), 'defer' => true, 'data-domain' => 'example.com']],
            json_decode($result, true),
        );
    }

    public function test_the_laravel_snippet_is_a_blade_fragment_that_only_renders_in_production(): void
    {
        $site = Site::create(['domain' => 'example.com']);
        $text = $this->snippets($site)['laravel']['text'];

        $this->assertStringNotContainsString('data-domain', Blade::render($text));

        $this->app['env'] = 'production';
        $this->assertStringContainsString('data-domain="example.com"', Blade::render($text));
    }

    /**
     * @param  string[]  $extraFrameworks
     * @return array<string, array{where: string, text: string}>
     */
    private function snippets(Site $site, array $extraFrameworks = []): array
    {
        $module = $this->temporaryFile('mjs', file_get_contents(public_path('assets/js/snippets.js')));
        $options = json_encode(['domain' => $site->domain, 'src' => self::ORIGIN.'/js/'.$site->scriptName()]);

        $script = "import { FRAMEWORKS, snippetFor } from 'file://{$module}';"
            .'const keys = [...FRAMEWORKS.map(([key]) => key), ...'.json_encode($extraFrameworks).'];'
            ."console.log(JSON.stringify(Object.fromEntries(keys.map((key) => [key, snippetFor(key, {$options})]))));";

        return json_decode($this->runNode($script, module: true), true);
    }

    private function runNode(string $script, bool $module = false): string
    {
        if (Process::run('node --version')->failed()) {
            $this->markTestSkipped('Node is not installed.');
        }

        $file = $this->temporaryFile($module ? 'mjs' : 'js', $script);
        $result = Process::run(['node', $file]);

        $this->assertTrue($result->successful(), $result->errorOutput());

        return trim($result->output());
    }

    private function temporaryFile(string $extension, string $contents): string
    {
        $path = tempnam(sys_get_temp_dir(), 'snippets');
        rename($path, $path .= '.'.$extension);
        file_put_contents($path, $contents);

        return $this->temporaryFiles[] = $path;
    }
}
